import hashlib
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
LF = ROOT / "level_factory"
PINS = {'apps/cli/commands/__init__.py': '85bad8aa6b1bcf97', 'adapters/zoo/__init__.py': '2b9f83962f9b526f', 'tests/unit/test_fixture_pipeline.py': 'ac3943f9ba35e5e9'}
EDITS = {'apps/cli/commands/__init__.py': [('lines 980-981', '                        specs[job.job_id]["sign_pack"] = door\n            elif job.stage_id == "zoo_roof_props_build":\n', '                        specs[job.job_id]["sign_pack"] = door\n                        # ONE SIGN A BUILDING (0.241.0). The walker, walking\n                        # cold run 9386, of a pharmacy with its band along the\n                        # parapet and a lit box over its door: "in real life\n                        # this would be 1 sign". A shell dealt a band keeps\n                        # the band and builds no door box (Zoo 1.123.0\'s\n                        # `--skip-fixture-types`); Lot 0.129.0 leaves that\n                        # box\'s lamp out of the site\'s lights. A shell dealt\n                        # none keeps its box as its one sign.\n                        specs[job.job_id]["skip_fixture_types"] = ["sign"]\n            elif job.stage_id == "zoo_roof_props_build":\n')], 'adapters/zoo/__init__.py': [('lines 328-329', '                             *[str(t) for t in job_spec["fixture_types"]]]\n            # the business the shell\'s band was dealt (0.148.0): its door box\n', '                             *[str(t) for t in job_spec["fixture_types"]]]\n            # one sign a building (0.241.0): what this shell leaves out, as ONE\n            # comma list -- Zoo\'s CLI reads `--fixture-types` and this the same way\n            if job_spec.get("skip_fixture_types"):\n                zoo_args += ["--skip-fixture-types",\n                             ",".join(str(t) for t in job_spec["skip_fixture_types"])]\n            # the business the shell\'s band was dealt (0.148.0): its door box\n')], 'tests/unit/test_fixture_pipeline.py': [('lines 87-88', '    assert args[args.index("--sign-pack") + 1] == pack\n\n', '    assert args[args.index("--sign-pack") + 1] == pack\n\n\ndef test_a_banded_shell_s_fixtures_leave_out_its_door_box(tmp_path):\n    """0.241.0, one sign a building (the walker, cold run 9386): a fixtures job told to skip `sign` passes Zoo\n    `--skip-fixture-types sign` as one comma list, and the planner tells every shell it deals a band to. FAILS ON\n    0.240.0."""\n    lights = tmp_path / "shell.lights.json"\n    lights.write_text(json.dumps({\n        "light_manifest_version": "1.1", "building_id": "lf_m1",\n        "anchors": [{"id": "a", "type": "sign", "pos": [0, 0, 3]}]}))\n    spec = {"mode": "fixtures", "lights_path": str(lights), "theme": "delco",\n            "skip_fixture_types": ["sign", "neon"]}\n    cmds = ZooAdapter().plan_commands(spec, {\n        "repository": str(tmp_path), "work_dir": str(tmp_path / "work"),\n        "blender_executable": "blender"})\n    args = list(cmds[0].arguments)\n    assert args[args.index("--skip-fixture-types") + 1] == "sign,neon"\n    src = (Path(__file__).resolve().parents[2] / "apps" / "cli" / "commands" / "__init__.py").read_text(\n        encoding="utf-8")\n    at = src.index(\'specs[job.job_id]["sign_pack"] = door\')\n    assert \'specs[job.job_id]["skip_fixture_types"] = ["sign"]\' in src[at:at + 900]\n\n')]}
NEW_FILES = {}
CHANGELOG = '## [0.241.0] - one sign a building: a banded shell builds no door box\n\n**The walker, walking cold run 9386** (the factory\'s `docs/findings/walk_2026-10-23_9386/`, finding 1): a pharmacy\'s\nband along the parapet and a lit box over its door -- "in real life this would be 1 sign".\n\n### Changed\n- **A shell dealt a band builds no door box**: its fixtures job is told `skip_fixture_types: ["sign"]`, which reaches\n  Zoo 1.123.0 as `--skip-fixture-types sign`, one comma list. Lot 0.129.0 leaves that box\'s lamp out of the site\'s\n  lights. A shell dealt none keeps its box. The door pack (0.148.0) is still handed over; with no `sign` anchor built\n  there is nothing for it to dress.\n\n### Noted, not changed\n- The adapter passes `--fixture-types` as separate arguments, and Zoo\'s CLI reads one comma list. Nothing sets\n  `fixture_types` today, so it has never run; the new flag is passed the way the CLI reads it.\n\n### Tests\n- `tests/unit/test_fixture_pipeline.py::test_a_banded_shell_s_fixtures_leave_out_its_door_box` (fails on 0.240.0).\n\n'
OLD_VERSION, NEW_VERSION = '0.240.1', '0.241.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
